export const createJsonFile = async (dirHandle: FileSystemDirectoryHandle | MockDirectoryHandle, name: string): Promise<void> => {
    // Basic validation, default to json if no extension
    let fileName = name;
    if (!fileName.includes('.')) fileName += '.json';

    await dirHandle.getFileHandle(fileName, { create: true });
};

export const createDirectory = async (dirHandle: FileSystemDirectoryHandle | MockDirectoryHandle, name: string): Promise<FileSystemDirectoryHandle | MockDirectoryHandle> => {
    // @ts-ignore
    return await dirHandle.getDirectoryHandle(name, { create: true });
};

export const deleteEntry = async (dirHandle: FileSystemDirectoryHandle | MockDirectoryHandle, name: string): Promise<void> => {
    await dirHandle.removeEntry(name, { recursive: true });
};

// --- Advanced Operations (Move, Rename, EnsureStructure) ---

/**
 * Ensures a deep directory path exists. 
 * @param rootHandle The root folder handle
 * @param pathString e.g. "Loot/Spawners/Presets/Override"
 */
export const ensureDirectoryPath = async (rootHandle: FileSystemDirectoryHandle | MockDirectoryHandle, pathString: string) => {
    const parts = pathString.split('/').filter(p => p);
    let current = rootHandle;
    for (const part of parts) {
        // @ts-ignore
        current = await current.getDirectoryHandle(part, { create: true });
    }
};

/**
 * Renames an entry by copying content (if file) and deleting old.
 * Note: Directory renaming is complex recursively, focusing on File rename mainly.
 */
export const renameEntry = async (parentHandle: FileSystemDirectoryHandle | MockDirectoryHandle, oldName: string, newName: string, kind: 'file' | 'directory') => {
    if (oldName === newName) return;

    if (kind === 'file') {
        // @ts-ignore
        const oldHandle = await parentHandle.getFileHandle(oldName);
        const oldFile = await oldHandle.getFile();
        const content = await oldFile.text();

        // @ts-ignore
        const newHandle = await parentHandle.getFileHandle(newName, { create: true });
        const writable = await newHandle.createWritable();
        await writable.write(content);
        await writable.close();

        await parentHandle.removeEntry(oldName);
    } else {
        // Use moveDirectory for rename logic
        await moveDirectory(parentHandle, parentHandle, oldName, newName);
    }
};

/**
 * Recursively moves a directory.
 */
export const moveDirectory = async (
    sourceParent: FileSystemDirectoryHandle | MockDirectoryHandle,
    destParent: FileSystemDirectoryHandle | MockDirectoryHandle,
    dirName: string,
    newDirName?: string // Optional new name for rename-move support
) => {
    const targetName = newDirName || dirName;

    // Safety check: Don't move if source parent IS dest parent AND name is same
    if (await sourceParent.isSameEntry(destParent as any) && dirName === targetName) {
        return;
    }

    // 1. Get Source Handle
    // @ts-ignore
    const sourceHandle = await sourceParent.getDirectoryHandle(dirName);

    // 2. Create Destination Handle
    // @ts-ignore
    const destHandle = await destParent.getDirectoryHandle(targetName, { create: true });

    // 3. Iterate and move children
    // @ts-ignore
    for await (const entry of sourceHandle.values()) {
        if (entry.kind === 'file') {
            await moveFile(sourceHandle, destHandle, entry.name);
        } else if (entry.kind === 'directory') {
            await moveDirectory(sourceHandle, destHandle, entry.name);
        }
    }

    // 4. Delete Source Directory
    await sourceParent.removeEntry(dirName, { recursive: true });
};

/**
 * Moves a file from one directory handle to another.
 */
export const moveFile = async (
    sourceParent: FileSystemDirectoryHandle | MockDirectoryHandle, 
    destParent: FileSystemDirectoryHandle | MockDirectoryHandle, 
    fileName: string
) => {
    // Safety check: Don't move if source parent IS dest parent
    if (await sourceParent.isSameEntry(destParent as any)) {
        return;
    }

    // 1. Read
    // @ts-ignore
    const sourceHandle = await sourceParent.getFileHandle(fileName);
    const file = await sourceHandle.getFile();
    const content = await file.text();

    // 2. Write to new
    // @ts-ignore
    const destHandle = await destParent.getFileHandle(fileName, { create: true });
    const writable = await destHandle.createWritable();
    await writable.write(content);
    await writable.close();

    // 3. Delete old
    await sourceParent.removeEntry(fileName);
};

import React, { useState, useEffect, useMemo } from 'react';
import { useI18n } from '../i18n';
import { BooleanToggle } from './FormControls';
import { SearchIcon, SaveIcon, Cog6ToothIcon } from './Icons';

interface ServerSettingsEditorProps {
    content: string;
    onChange: (newContent: string) => void;
}

// Map<SectionName, Map<Key, Value>>
type IniData = Record<string, Record<string, string>>;

export const ServerSettingsEditor: React.FC<ServerSettingsEditorProps> = ({ content, onChange }) => {
    const { t } = useI18n();
    const [searchTerm, setSearchTerm] = useState("");
    const [parsedData, setParsedData] = useState<IniData>({});

    // Parse INI on load
    useEffect(() => {
        const lines = content.split(/\r?\n/);
        const data: IniData = {};
        let currentSection = "";

        lines.forEach(line => {
            const trimmed = line.trim();
            if (!trimmed || trimmed.startsWith(';') || trimmed.startsWith('#')) return;

            if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
                currentSection = trimmed.slice(1, -1);
                data[currentSection] = {};
            } else if (currentSection && trimmed.includes('=')) {
                const eqIdx = trimmed.indexOf('=');
                const key = trimmed.substring(0, eqIdx).trim();
                const val = trimmed.substring(eqIdx + 1).trim();
                data[currentSection][key] = val;
            }
        });
        setParsedData(data);
    }, [content]);

    const handleUpdate = (section: string, key: string, value: string | boolean) => {
        const newData = { ...parsedData };
        if (!newData[section]) newData[section] = {};

        let stringVal = String(value);
        // Ensure standard casing for booleans in SCUM INI
        if (typeof value === 'boolean') {
            stringVal = value ? "True" : "False";
        }

        newData[section][key] = stringVal;
        setParsedData(newData);

        // Reconstruct INI string
        let newContent = "";
        Object.keys(newData).forEach(sec => {
            newContent += `[${sec}]\n`;
            Object.entries(newData[sec]).forEach(([k, v]) => {
                newContent += `${k}=${v}\n`;
            });
            newContent += "\n";
        });

        onChange(newContent.trim());
    };

    const sections = Object.keys(parsedData);

    // Filtering logic
    const filteredSections = useMemo(() => {
        if (!searchTerm) return sections;
        const lowerSearch = searchTerm.toLowerCase();

        return sections.filter(sec => {
            // Check section name
            if (sec.toLowerCase().includes(lowerSearch)) return true;
            // Check keys within section
            const keys = Object.keys(parsedData[sec]);
            return keys.some(k => k.toLowerCase().includes(lowerSearch));
        });
    }, [sections, parsedData, searchTerm]);

    const getSectionColor = (name: string) => {
        switch(name) {
            case 'General': return 'text-scum-accent';
            case 'World': return 'text-green-400';
            case 'Respawn': return 'text-red-400';
            case 'Vehicles': return 'text-yellow-400';
            case 'Damage': return 'text-orange-400';
            case 'Features': return 'text-purple-400';
            default: return 'text-gray-300';
        }
    };

    return (
        <div className="flex flex-col h-full bg-[#0b1120] text-gray-200">
            {/* Header */}
            <div className="p-6 pb-4 border-b border-white/5 flex flex-col gap-4 sticky top-0 bg-[#0b1120]/95 backdrop-blur-xl z-20">
                <div className="flex justify-between items-center">
                    <h2 className="text-xl font-bold text-gray-100 flex items-center gap-2">
                        <Cog6ToothIcon className="w-6 h-6 text-gray-500" />
                        Server Configuration
                    </h2>
                    <div className="text-xs text-gray-500 font-mono">ServerSettings.ini</div>
                </div>

                <div className="relative group">
                    <input 
                        type="text" 
                        className="w-full bg-scum-900 border border-scum-700 rounded-lg py-2 pl-9 pr-4 text-sm focus:outline-none focus:border-scum-accent transition-all placeholder-gray-600 focus:shadow-[0_0_15px_rgba(6,182,212,0.15)]"
                        placeholder="Search settings..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                    <SearchIcon className="absolute left-3 top-2.5 w-4 h-4 text-gray-500 group-focus-within:text-scum-accent transition-colors" />
                </div>
            </div>

            {/* Content */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-8 pb-20">
                {filteredSections.map(section => {
                    const keys = Object.keys(parsedData[section]);
                    const visibleKeys = searchTerm 
                        ? keys.filter(k => k.toLowerCase().includes(searchTerm.toLowerCase()) || section.toLowerCase().includes(searchTerm.toLowerCase()))
                        : keys;

                    if (visibleKeys.length === 0) return null;

                    return (
                        <div key={section} className="animate-slide-up">
                            <div className="flex items-center gap-2 mb-4 border-b border-white/5 pb-2">
                                <span className={`text-sm font-bold uppercase tracking-widest ${getSectionColor(section)}`}>[{section}]</span>
                                <span className="text-[10px] bg-white/5 px-2 py-0.5 rounded text-gray-500">{visibleKeys.length}</span>
                            </div>

                            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                                {visibleKeys.map(key => {
                                    const value = parsedData[section][key];
                                    const isBool = value.toLowerCase() === 'true' || value.toLowerCase() === 'false';
                                    const cleanKey = key.replace('scum.', '');

                                    return (
                                        <div key={key} className="bg-scum-800/30 p-3 rounded-lg border border-white/5 flex flex-col gap-2 hover:bg-scum-800/50 transition-colors group">
                                            <label className="text-xs font-bold text-gray-400 group-hover:text-gray-200 transition-colors truncate" title={key}>
                                                {cleanKey}
                                            </label>

                                            {isBool ? (
                                                <BooleanToggle 
                                                    label={value.toLowerCase() === 'true' ? 'Enabled' : 'Disabled'}
                                                    value={value.toLowerCase() === 'true'}
                                                    onChange={(v) => handleUpdate(section, key, v)}
                                                    color={value.toLowerCase() === 'true' ? 'cyan' : 'fuchsia'}
                                                    size="sm"
                                                />
                                            ) : (
                                                <input 
                                                    type="text" 
                                                    className="w-full bg-black/30 border border-white/10 rounded px-2 py-1.5 text-sm text-white font-mono focus:outline-none focus:border-scum-accent transition-colors"
                                                    value={value}
                                                    onChange={(e) => handleUpdate(section, key, e.target.value)}
                                                />
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    );
                })}

                {filteredSections.length === 0 && (
                    <div className="text-center py-12 text-gray-500 italic">No matching settings found.</div>
                )}
            </div>
        </div>
    );
};

