                                        {sectionTrans && <span className="text-[9px] text-gray-500 font-mono">{section}</span>}
                                    </div>
                                    <span className="text-[10px] bg-white/5 px-2 py-0.5 rounded text-gray-500 border border-white/5 ml-2">{visibleKeys.length}</span>
