                                <div className="grid grid-cols-1 lg:grid-cols-2 gap-3 animate-fade-in">
                                    {visibleKeys.map(key => {
                                        const value = parsedData[section][key];
                                        const isBool = value.toLowerCase() === 'true' || value.toLowerCase() === 'false';

                                        // Robust key cleaning for translation: remove optional "scum." prefix (case-insensitive)
                                        const cleanKey = key.replace(/^scum\./i, '');
                                        // Try exact key first, then cleaned key
                                        const transKey = getSettingTranslation(key) || getSettingTranslation(cleanKey);
                                        const description = serverSettingsDescriptions[cleanKey] || serverSettingsDescriptions[key];

                                        return (
                                            <div 
                                                key={key} 
                                                className="bg-scum-800/30 rounded-lg border border-white/5 hover:bg-scum-800/50 transition-colors group px-4 py-3 flex flex-col gap-2 relative overflow-visible"
                                            >
                                                {/* Tooltip Popup */}
                                                {description && (
                                                    <div className="absolute left-0 bottom-full mb-2 w-full z-50 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-200 px-2 transform translate-y-1 group-hover:translate-y-0">
                                                        <div className="bg-black/90 text-gray-300 text-xs p-3 rounded-lg border border-scum-accent/30 shadow-[0_4px_20px_rgba(0,0,0,0.5)] backdrop-blur-md relative">
                                                            <div className="font-bold text-scum-accent mb-1 flex items-center gap-1">
                                                                <span className="w-1.5 h-1.5 rounded-full bg-scum-accent"></span> 
                                                                Info
                                                            </div>
                                                            {description}
                                                            {/* Arrow */}
                                                            <div className="absolute top-full left-6 -mt-[1px] border-4 border-transparent border-t-black/90"></div>
                                                        </div>
                                                    </div>
                                                )}

                                                <div className="flex flex-col mb-1 relative">
                                                    <label className="text-xs font-bold text-gray-200 group-hover:text-white transition-colors break-words flex items-center justify-between cursor-help">
                                                        <span>{transKey || cleanKey}</span>
                                                        {description && <div className="w-1.5 h-1.5 rounded-full bg-white/20 group-hover:bg-scum-accent/50 transition-colors"></div>}
                                                    </label>
                                                    {transKey && <span className="text-[9px] text-gray-500 font-mono truncate select-all">{key}</span>}
                                                </div>

                                                {isBool ? (
                                                    <div className="w-full">
                                                        <BooleanToggle 
                                                            label={""} 
                                                            value={value.toLowerCase() === 'true'}
                                                            onChange={(v) => handleUpdate(section, key, v)}
                                                            color={value.toLowerCase() === 'true' ? 'cyan' : 'fuchsia'}
                                                            size="sm"
                                                        />
                                                    </div>
                                                ) : (
                                                    <input 
                                                        type="text" 
                                                        className="w-full bg-black/30 border border-white/10 rounded px-2 py-1.5 text-sm text-white font-mono focus:outline-none focus:border-scum-accent transition-colors shadow-inner"
                                                        value={value}
                                                        onChange={(e) => handleUpdate(section, key, e.target.value)}
                                                    />
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    );
                })}

                {filteredSections.length === 0 && (
                    <div className="text-center py-12 text-gray-500 italic">No matching settings found.</div>
                )}
            </div>
        </div>
    );
};

import { fuzzyMatch } from './helpers';
import { fileTranslations } from './translations/fileTranslations';
import { nodeTranslations } from './translations/nodeTranslations';
import { itemTranslations } from './translations/itemTranslations';
import { serverSettingsTranslations } from './translations/serverSettingsTranslations';
import { serverSettingsDescriptions } from './translations/serverSettingsDescriptions';

// Types
export type TranslationCategory = 'item' | 'node' | 'file' | 'global' | 'setting' | 'setting_desc';

export interface TranslationEntry {
    text: string;
    categories: TranslationCategory[]; // Changed from single category to array
}

export interface TranslationData {
    [key: string]: TranslationEntry;
}

const STORAGE_KEY_V1 = 'scum_translations';
const STORAGE_KEY_V2 = 'scum_translations_v2'; 
const STORAGE_KEY_V3 = 'scum_translations_v3'; // Bump version for new structure
const UPDATE_EVENT = 'scum_translations_updated';

// In-memory lookup maps
let itemMap: Record<string, string> = {};
let nodeMap: Record<string, string> = {};
let fileMap: Record<string, string> = {};
let settingsMap: Record<string, string> = {};
let settingDescMap: Record<string, string> = {};
let globalMap: Record<string, string> = {};

let customData: TranslationData = {};

const normalize = (key: string) => key.toLowerCase().trim();

const loadTranslations = () => {
    // 1. Load Defaults
    itemMap = { ...itemTranslations };
    nodeMap = { ...nodeTranslations };
    fileMap = { ...fileTranslations };
    settingsMap = { ...serverSettingsTranslations };
    settingDescMap = {};

    // Load descriptions with prefix
    Object.entries(serverSettingsDescriptions).forEach(([k, v]) => {
        settingDescMap[`DESC::${k}`] = v;
    });

    globalMap = {}; 

    // 2. Migration Logic
    try {
        const v3Stored = localStorage.getItem(STORAGE_KEY_V3);
        const v2Stored = localStorage.getItem(STORAGE_KEY_V2);
        const v1Stored = localStorage.getItem(STORAGE_KEY_V1);

        if (v3Stored) {
            customData = JSON.parse(v3Stored);
        } else if (v2Stored) {
            // Upgrade V2 to V3 (Single category -> Array)
            const v2Data = JSON.parse(v2Stored);
            customData = {};
            Object.entries(v2Data).forEach(([k, v]: [string, any]) => {
                customData[k] = { 
                    text: v.text, 
                    categories: v.category === 'global' ? ['global'] : [v.category] 
                };
            });
            localStorage.setItem(STORAGE_KEY_V3, JSON.stringify(customData));
        } else if (v1Stored) {
            // Upgrade V1 to V3
            const v1Data = JSON.parse(v1Stored);
            customData = {};
            Object.entries(v1Data).forEach(([k, v]) => {
                customData[k] = { text: String(v), categories: ['global'] };
            });
            localStorage.setItem(STORAGE_KEY_V3, JSON.stringify(customData));
        } else {
            customData = {};
        }
    } catch (e) {
        console.warn("Translation load error", e);
        customData = {};
    }

    // 3. Populate Maps based on active categories
    Object.entries(customData).forEach(([key, entry]) => {
        const { text, categories } = entry;

        if (categories.includes('global')) {
            globalMap[key] = text;
            itemMap[key] = text;
            nodeMap[key] = text;
            fileMap[key] = text;
            settingsMap[key] = text;
            settingDescMap[key] = text;
        } else {
            if (categories.includes('item')) itemMap[key] = text;
            if (categories.includes('node')) nodeMap[key] = text;
            if (categories.includes('file')) fileMap[key] = text;
            if (categories.includes('setting')) settingsMap[key] = text;
            if (categories.includes('setting_desc')) settingDescMap[key] = text;
        }
    });
};

loadTranslations();

if (typeof window !== 'undefined') {
    window.addEventListener('storage', (e) => {
        if (e.key === STORAGE_KEY_V3) {
            loadTranslations();
            window.dispatchEvent(new Event(UPDATE_EVENT));
        }
    });
}

export const subscribeToTranslationUpdates = (callback: () => void) => {
    const handler = () => callback();
    window.addEventListener(UPDATE_EVENT, handler);
    return () => window.removeEventListener(UPDATE_EVENT, handler);
};

// --- Lookup ---
const lookup = (key: string, primaryMap: Record<string, string>): string | null => {
    if (primaryMap[key]) return primaryMap[key];
    if (globalMap[key]) return globalMap[key];

    const lowerKey = normalize(key);
    const primaryMatch = Object.keys(primaryMap).find(k => normalize(k) === lowerKey);
    if (primaryMatch) return primaryMap[primaryMatch];

    const globalMatch = Object.keys(globalMap).find(k => normalize(k) === lowerKey);
    if (globalMatch) return globalMap[globalMatch];

    return null;
};

export const getItemTranslation = (id: string): string => lookup(id, itemMap) || id;
export const getNodeTranslation = (name: string): string => lookup(name, nodeMap) || name;
export const getFilePartTranslation = (part: string): string => lookup(part, fileMap) || part;
export const getSettingTranslation = (key: string): string => lookup(key, settingsMap) || "";
export const getSettingDescription = (key: string): string => lookup(`DESC::${key}`, settingDescMap) || "";

export const getFileNameTranslation = (filename: string): string => {
    const baseName = filename.replace(/\.json$/i, '');
    const parts = baseName.split(/([-_ ])/); 
    const translatedParts = parts.map(part => {
        if (part === '-' || part === '_' || part === ' ') return part;
        const translated = getFilePartTranslation(part);
        return translated !== part ? translated : part;
    });
    return translatedParts.join('');
};

export const hasTranslation = (id: string): boolean => {
    if (itemMap[id] || nodeMap[id] || fileMap[id] || globalMap[id] || settingsMap[id]) return true;
    const lower = normalize(id);
    const search = (map: Record<string, string>) => Object.keys(map).some(k => normalize(k) === lower);
    return search(itemMap) || search(nodeMap) || search(fileMap) || search(globalMap) || search(settingsMap);
};

// --- Management ---

export const saveTranslation = (key: string, value: string, category: TranslationCategory) => {
    const existing = customData[key];
    let newCategories: TranslationCategory[] = [];

    if (existing) {
        newCategories = [...existing.categories];
        if (category === 'global') {
            newCategories = ['global'];
        } else {
            if (!newCategories.includes(category)) {
                newCategories.push(category);
            }
        }
    } else {
        newCategories = [category];
    }

    customData[key] = { text: value, categories: newCategories };
    localStorage.setItem(STORAGE_KEY_V3, JSON.stringify(customData));
    loadTranslations();
    window.dispatchEvent(new Event(UPDATE_EVENT));
};

export const toggleTranslationCategory = (key: string, category: TranslationCategory, value: string) => {
    const existing = customData[key];
    let newCategories: TranslationCategory[] = existing ? [...existing.categories] : [];

    if (category === 'global') {
        if (newCategories.includes('global')) return; 
        newCategories = ['global'];
    } else {
        if (newCategories.includes('global')) newCategories = []; 

        if (newCategories.includes(category)) {
            newCategories = newCategories.filter(c => c !== category);
        } else {
            newCategories.push(category);
        }
    }

    if (newCategories.length === 0) {
        deleteTranslation(key);
    } else {
        customData[key] = { text: value, categories: newCategories };
        localStorage.setItem(STORAGE_KEY_V3, JSON.stringify(customData));
        loadTranslations();
        window.dispatchEvent(new Event(UPDATE_EVENT));
    }
};

export const deleteTranslation = (key: string) => {
    delete customData[key];
    localStorage.setItem(STORAGE_KEY_V3, JSON.stringify(customData));
    loadTranslations();
    window.dispatchEvent(new Event(UPDATE_EVENT));
};

export const bulkSaveTranslations = (updates: { key: string, value: string, category: TranslationCategory }[]) => {
    updates.forEach(item => {
        saveTranslation(item.key, item.value, item.category);
    });
};

export const bulkDeleteTranslations = (keys: string[]) => {
    keys.forEach(key => {
        delete customData[key];
    });
    localStorage.setItem(STORAGE_KEY_V3, JSON.stringify(customData));
    loadTranslations();
    window.dispatchEvent(new Event(UPDATE_EVENT));
};

export const importTranslations = (jsonContent: any) => {
    try {
        Object.entries(jsonContent).forEach(([k, v]: [string, any]) => {
            if (typeof v === 'string') {
                customData[k] = { text: v, categories: ['global'] };
            } else if (typeof v === 'object' && v.text) {
                const cats = Array.isArray(v.categories) ? v.categories : (v.category ? [v.category] : ['global']);
                customData[k] = { text: v.text, categories: cats };
            }
        });
        localStorage.setItem(STORAGE_KEY_V3, JSON.stringify(customData));
        loadTranslations();
        window.dispatchEvent(new Event(UPDATE_EVENT));
        return true;
    } catch(e) {
        return false;
    }
};

export const exportTranslations = (): string => {
    return JSON.stringify(customData, null, 4);
};

export const resetTranslations = () => {
    localStorage.removeItem(STORAGE_KEY_V3);
    loadTranslations();
    window.dispatchEvent(new Event(UPDATE_EVENT));
};

export const getAllTranslations = (): { key: string, value: string, categories: TranslationCategory[], isCustom: boolean }[] => {
    const list: { key: string, value: string, categories: TranslationCategory[], isCustom: boolean }[] = [];
    const seen = new Set<string>();

    Object.entries(customData).forEach(([k, v]) => {
        list.push({ key: k, value: v.text, categories: v.categories, isCustom: true });
        seen.add(k);
    });

    const addDefaults = (map: Record<string, string>, cat: TranslationCategory) => {
        Object.entries(map).forEach(([k, v]) => {
            if (!seen.has(k)) {
                list.push({ key: k, value: v, categories: [cat], isCustom: false });
                seen.add(k);
            }
        });
    };

    addDefaults(itemTranslations, 'item');
    addDefaults(nodeTranslations, 'node');
    addDefaults(fileTranslations, 'file');
    addDefaults(serverSettingsTranslations, 'setting');
    addDefaults(settingDescMap, 'setting_desc');

    return list.sort((a, b) => a.key.localeCompare(b.key));
};

export const getIdsByTranslationMatch = (term: string): string[] => {
    if (!term) return [];
    const lower = normalize(term);
    const all = getAllTranslations();
    return all.filter(t => t.value.toLowerCase().includes(lower)).map(t => t.key);
};

export const getIdsByFuzzyTranslationMatch = (term: string): string[] => {
    if (!term) return [];
    const all = getAllTranslations();
    return all.filter(t => fuzzyMatch(t.value, term)).map(t => t.key);
};

import React, { useState, useMemo, useEffect } from 'react';
import { useI18n } from '../i18n';
import { getAllTranslations, saveTranslation, deleteTranslation, importTranslations, exportTranslations, resetTranslations, subscribeToTranslationUpdates, TranslationCategory, bulkSaveTranslations, bulkDeleteTranslations, toggleTranslationCategory } from '../utils/itemTranslator';
import { SearchIcon, ArrowPathIcon, ArrowDownTrayIcon, ArrowUpTrayIcon, TrashIcon, PlusIcon, CheckCircleIcon, XMarkIcon } from './Icons';

interface TranslationManagerProps {
    onBack: () => void;
}

type FilterCategory = TranslationCategory | 'all' | 'custom';

export const TranslationManager: React.FC<TranslationManagerProps> = ({ onBack }) => {
    const { t } = useI18n();
    const [searchTerm, setSearchTerm] = useState("");
    const [filterCategory, setFilterCategory] = useState<FilterCategory>('all');
    const [translations, setTranslations] = useState<{ key: string, value: string, categories: TranslationCategory[], isCustom: boolean }[]>([]);

    // Add New State
    const [newKey, setNewKey] = useState("");
    const [newValue, setNewValue] = useState("");
    const [newCategory, setNewCategory] = useState<TranslationCategory>('item');

    // Edit State
    const [editingKey, setEditingKey] = useState<string | null>(null);
    const [editingValue, setEditingValue] = useState("");

    // Bulk Edit State
    const [isBulkMode, setIsBulkMode] = useState(false);
    const [selectedKeys, setSelectedKeys] = useState<Set<string>>(new Set());

    const refreshData = () => {
        setTranslations(getAllTranslations());
    };

    useEffect(() => {
        refreshData();
        const unsubscribe = subscribeToTranslationUpdates(() => {
            refreshData();
        });
        return () => unsubscribe();
    }, []);

    const filteredList = useMemo(() => {
        let list = translations;

        if (filterCategory !== 'all') {
            if (filterCategory === 'custom') {
                list = list.filter((t) => t.isCustom);
            } else {
                // If filtering by specific category, show items that HAVE that category (or global)
                list = list.filter((t) => t.categories.includes(filterCategory as TranslationCategory) || t.categories.includes('global'));
            }
        }

        if (searchTerm) {
            const lower = searchTerm.toLowerCase();
            list = list.filter((t) => t.key.toLowerCase().includes(lower) || t.value.toLowerCase().includes(lower));
        }

        return list;
    }, [translations, filterCategory, searchTerm]);

    const handleSaveEdit = () => {
        if (editingKey) {
            const entry = translations.find(t => t.key === editingKey);
            if(entry) {
                const cat = entry.categories[0] || 'global';
                saveTranslation(editingKey, editingValue, cat);
            }
            setEditingKey(null);
        }
    };

    const handleDelete = (key: string) => {
        if (confirm(t('common.confirmDelete'))) {
            deleteTranslation(key);
        }
    };

    const handleAddNew = () => {
        if (!newKey || !newValue) return;

        let finalKey = newKey;
        // Auto-prefix for descriptions if user didn't type it
        if (newCategory === 'setting_desc' && !finalKey.startsWith('DESC::')) {
            finalKey = `DESC::${finalKey}`;
        }

        saveTranslation(finalKey, newValue, newCategory);
        setNewKey("");
        setNewValue("");
        setNewCategory("item");
    };

    const handleExport = () => {
        const json = exportTranslations();
        const blob = new Blob([json], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = "scum_custom_translations_v3.json";
        a.click();
    };

    const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (!e.target.files || e.target.files.length === 0) return;
        const file = e.target.files[0];
        const reader = new FileReader();
        reader.onload = (ev) => {
            try {
                const json = JSON.parse(ev.target?.result as string);
                if (importTranslations(json)) {
                    alert(t('settings.transImportSuccess'));
                } else {
                    alert(t('settings.transImportFail'));
                }
            } catch (err) {
                alert(t('settings.transImportFail'));
            }
        };
        reader.readAsText(file);
    };

    const handleReset = () => {
        if(confirm(t('trans.confirmReset'))) resetTranslations();
    };

    const toggleBulkMode = () => {
        setIsBulkMode(!isBulkMode);
        setSelectedKeys(new Set());
    };

    const handleSelect = (key: string) => {
        const newSet = new Set(selectedKeys);
        if (newSet.has(key)) newSet.delete(key);
        else newSet.add(key);
        setSelectedKeys(newSet);
    };

    const handleSelectAll = () => {
        if (selectedKeys.size === filteredList.length) {
            setSelectedKeys(new Set());
        } else {
            const newSet = new Set(selectedKeys);
            filteredList.forEach(t => newSet.add(t.key));
            setSelectedKeys(newSet);
        }
    };

    const handleBulkDelete = () => {
        if (selectedKeys.size === 0) return;
        if (confirm(t('trans.confirmBulkDelete', [selectedKeys.size]))) {
            bulkDeleteTranslations(Array.from(selectedKeys));
            setSelectedKeys(new Set());
        }
    };

    // Render category pills
    const CategoryToggle = ({ item }: { item: typeof translations[0] }) => {
        const isGlobal = item.categories.includes('global');

        return (
            <div className="flex gap-1 flex-wrap justify-end">
                {isGlobal ? (
                    <button 
                        className="text-[10px] uppercase font-bold px-3 py-1 rounded border border-green-500/30 bg-green-500/20 text-green-400 hover:bg-green-500/30 transition-colors cursor-help"
                        title="Global (Merged)"
                        onClick={() => toggleTranslationCategory(item.key, 'global', item.value)}
                    >
                        GLOBAL
                    </button>
                ) : (
                    <>
                        {['item', 'node', 'file', 'setting', 'setting_desc'].map((cat) => {
                            const isActive = item.categories.includes(cat as TranslationCategory);
                            let color = "";
                            let label = cat;

                            if (cat === 'item') color = isActive ? "bg-blue-500/20 text-blue-300 border-blue-500/30" : "text-gray-600 border-gray-700 hover:border-blue-500/30";
                            if (cat === 'node') color = isActive ? "bg-pink-500/20 text-pink-300 border-pink-500/30" : "text-gray-600 border-gray-700 hover:border-pink-500/30";
                            if (cat === 'file') color = isActive ? "bg-yellow-500/20 text-yellow-300 border-yellow-500/30" : "text-gray-600 border-gray-700 hover:border-yellow-500/30";
                            if (cat === 'setting') {
                                color = isActive ? "bg-cyan-500/20 text-cyan-300 border-cyan-500/30" : "text-gray-600 border-gray-700 hover:border-cyan-500/30";
                                label = "INI Key";
                            }
                            if (cat === 'setting_desc') {
                                color = isActive ? "bg-purple-500/20 text-purple-300 border-purple-500/30" : "text-gray-600 border-gray-700 hover:border-purple-500/30";
                                label = "INI Hint";
                            }

                            return (
                                <button
                                    key={cat}
                                    onClick={() => toggleTranslationCategory(item.key, cat as TranslationCategory, item.value)}
                                    className={`text-[10px] uppercase font-bold px-2 py-1 rounded border transition-colors whitespace-nowrap ${color}`}
                                >
                                    {label}
                                </button>
                            );
                        })}
                    </>
                )}
            </div>
        );
    };

    return (
        <div className="flex flex-col h-full bg-[#0b1120] text-gray-200 animate-fade-in absolute inset-0 z-50">
            {/* Header */}
            <div className="h-16 border-b border-scum-700/50 bg-[#0f172a]/90 backdrop-blur-xl flex items-center justify-between px-6 shrink-0 shadow-lg z-20">
                <div className="flex items-center gap-4">
                    <button onClick={onBack} className="p-2 hover:bg-red-500/20 rounded-full transition-colors text-gray-400 hover:text-white" title="Close">
                        <XMarkIcon className="w-5 h-5" />
                    </button>
                    <h2 className="text-xl font-bold text-scum-accent tracking-widest uppercase flex items-center gap-3">
                        <span className="text-2xl filter drop-shadow-[0_0_10px_rgba(6,182,212,0.5)]">🌐</span> {t('trans.title')}
                    </h2>
                </div>

                <div className="flex items-center gap-3">
                    <button 
                        onClick={toggleBulkMode}
                        className={`flex items-center gap-2 px-4 py-2 rounded-lg border transition-all text-xs font-bold ${isBulkMode ? 'bg-scum-accent text-black border-scum-accent shadow-[0_0_10px_rgba(6,182,212,0.4)]' : 'bg-transparent text-gray-400 border-gray-600 hover:text-white'}`}
                    >
                        <CheckCircleIcon className="w-4 h-4" /> {t('trans.bulkEdit')}
                    </button>
                    <div className="h-6 w-px bg-white/10 mx-1"></div>
                    <button onClick={handleReset} className="flex items-center gap-2 px-4 py-2 rounded-lg bg-red-900/20 text-red-400 border border-red-500/30 hover:bg-red-500 hover:text-white transition-all text-xs font-bold active:scale-95">
                        <ArrowPathIcon className="w-4 h-4" /> {t('trans.delete')}
                    </button>
                    <button onClick={handleExport} className="flex items-center gap-2 px-4 py-2 rounded-lg bg-scum-800 border border-scum-700 text-gray-300 hover:text-white hover:border-scum-500 transition-all text-xs font-bold active:scale-95">
                        <ArrowDownTrayIcon className="w-4 h-4" /> {t('settings.exportTrans')}
                    </button>
