import React, { useState, useEffect, useMemo } from 'react';
import { useI18n } from '../i18n';
import { BooleanToggle } from './FormControls';
import { SearchIcon, Cog6ToothIcon, ChevronDown, ChevronRight, CheckCircleIcon } from './Icons';
import { getSettingTranslation, getSettingDescription } from '../utils/itemTranslator';

interface ServerSettingsEditorProps {
    content: string;
    onChange: (newContent: string) => void;
}

// Map<SectionName, Map<Key, Value>>
type IniData = Record<string, Record<string, string>>;

export const ServerSettingsEditor: React.FC<ServerSettingsEditorProps> = ({ content, onChange }) => {
    const { t } = useI18n();
    const [searchTerm, setSearchTerm] = useState("");
    const [parsedData, setParsedData] = useState<IniData>({});
    const [collapsedSections, setCollapsedSections] = useState<Set<string>>(new Set());

    // Parse INI on load
    useEffect(() => {
        const lines = content.split(/\r?\n/);
        const data: IniData = {};
        let currentSection = "";

        lines.forEach(line => {
            const trimmed = line.trim();
            if (!trimmed || trimmed.startsWith(';') || trimmed.startsWith('#')) return;

            if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
                currentSection = trimmed.slice(1, -1);
                data[currentSection] = {};
            } else if (currentSection && trimmed.includes('=')) {
                const eqIdx = trimmed.indexOf('=');
                const key = trimmed.substring(0, eqIdx).trim();
                const val = trimmed.substring(eqIdx + 1).trim();
                data[currentSection][key] = val;
            }
        });
        setParsedData(data);
    }, [content]);

    const handleUpdate = (section: string, key: string, value: string | boolean) => {
        const newData = { ...parsedData };
        if (!newData[section]) newData[section] = {};

        let stringVal = String(value);
        // Ensure standard casing for booleans in SCUM INI
        if (typeof value === 'boolean') {
            stringVal = value ? "True" : "False";
        }

        newData[section][key] = stringVal;
        setParsedData(newData);

        // Reconstruct INI string
        let newContent = "";
        Object.keys(newData).forEach(sec => {
            newContent += `[${sec}]\n`;
            Object.entries(newData[sec]).forEach(([k, v]) => {
                newContent += `${k}=${v}\n`;
            });
            newContent += "\n";
        });

        onChange(newContent.trim());
    };

    const toggleSection = (section: string) => {
        const newSet = new Set(collapsedSections);
        if (newSet.has(section)) newSet.delete(section);
        else newSet.add(section);
        setCollapsedSections(newSet);
    };

    const sections = Object.keys(parsedData);

    // Filtering logic
    const filteredSections = useMemo(() => {
        if (!searchTerm) return sections;
        const lowerSearch = searchTerm.toLowerCase();

        return sections.filter(sec => {
            // Check section name
            if (sec.toLowerCase().includes(lowerSearch)) return true;
            // Check translated section name
            const transSection = getSettingTranslation(sec);
            if (transSection && transSection.toLowerCase().includes(lowerSearch)) return true;

            // Check keys within section
            const keys = Object.keys(parsedData[sec]);
            return keys.some(k => {
                if (k.toLowerCase().includes(lowerSearch)) return true;
                const cleanKey = k.replace(/^scum\./i, '');
                const transKey = getSettingTranslation(k) || getSettingTranslation(cleanKey);
                return transKey && transKey.toLowerCase().includes(lowerSearch);
            });
        });
    }, [sections, parsedData, searchTerm]);

    const getSectionColor = (name: string) => {
        switch(name) {
            case 'General': return 'text-scum-accent border-scum-accent/50';
            case 'SCUM.GameMode': 
            case 'GameMode': return 'text-green-400 border-green-500/50';
            case 'SCUM.RespawnSettings':
            case 'Respawn': return 'text-red-400 border-red-500/50';
            case 'SCUM.Vehicles':
            case 'Vehicles': return 'text-yellow-400 border-yellow-500/50';
            case 'SCUM.WorldSettings':
            case 'World': return 'text-blue-400 border-blue-500/50';
            default: return 'text-gray-300 border-gray-600/50';
        }
    };

    return (
        <div className="flex flex-col h-full bg-[#0b1120] text-gray-200">
            {/* Header */}
            <div className="p-6 pb-4 border-b border-white/5 flex flex-col gap-4 sticky top-0 bg-[#0b1120]/95 backdrop-blur-xl z-20 shadow-lg">
                <div className="flex justify-between items-center">
                    <h2 className="text-xl font-bold text-gray-100 flex items-center gap-2">
                        <Cog6ToothIcon className="w-6 h-6 text-scum-accent" />
                        {t('serverSettings.title')}
                    </h2>
                    <div className="text-xs text-gray-500 font-mono">ServerSettings.ini</div>
                </div>

                <div className="relative group">
                    <input 
                        type="text" 
                        className="w-full bg-scum-900 border border-scum-700 rounded-lg py-2 pl-9 pr-4 text-sm focus:outline-none focus:border-scum-accent transition-all placeholder-gray-600 focus:shadow-[0_0_15px_rgba(6,182,212,0.15)]"
                        placeholder={t('explorer.search')}
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                    <SearchIcon className="absolute left-3 top-2.5 w-4 h-4 text-gray-500 group-focus-within:text-scum-accent transition-colors" />
                </div>
            </div>

            {/* Content */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-6 pb-20">
                {filteredSections.map(section => {
                    const keys = Object.keys(parsedData[section]);
                    const visibleKeys = searchTerm 
                        ? keys.filter(k => {
                            const cleanKey = k.replace(/^scum\./i, '');
                            if (k.toLowerCase().includes(searchTerm.toLowerCase())) return true;

                            const trans = getSettingTranslation(k) || getSettingTranslation(cleanKey);
                            if (trans && trans.toLowerCase().includes(searchTerm.toLowerCase())) return true;

                            // Also show all keys if section matches
                            const sectionTrans = getSettingTranslation(section);
                            return section.toLowerCase().includes(searchTerm.toLowerCase()) || (sectionTrans && sectionTrans.toLowerCase().includes(searchTerm.toLowerCase()));
                        })
                        : keys;

                    if (visibleKeys.length === 0) return null;

                    const isCollapsed = collapsedSections.has(section) && !searchTerm;
                    const colorClass = getSectionColor(section);
                    const cleanSectionName = section.replace('SCUM.', '');
                    const sectionTrans = getSettingTranslation(section);

                    return (
                        <div key={section} className="animate-slide-up">
                            <div 
                                className={`flex items-center justify-between gap-2 mb-3 pb-2 border-b cursor-pointer group select-none ${colorClass.split(' ')[1]}`}
                                onClick={() => toggleSection(section)}
                            >
                                <div className="flex items-center gap-2">
                                    <span className={`transition-transform duration-200 ${isCollapsed ? '-rotate-90' : 'rotate-0'}`}>
                                        <ChevronDown className="w-4 h-4 opacity-50 group-hover:opacity-100" />
                                    </span>
                                    <div className="flex flex-col">
                                        <span className={`text-sm font-bold uppercase tracking-widest ${colorClass.split(' ')[0]}`}>
                                            {sectionTrans || cleanSectionName}
                                        </span>
                                        {sectionTrans && <span className="text-[9px] text-gray-500 font-mono">{section}</span>}
                                    </div>
                                    <span className="text-[10px] bg-white/5 px-2 py-0.5 rounded text-gray-500 border border-white/5 ml-2">{visibleKeys.length}</span>
                                </div>
                            </div>

                            {!isCollapsed && (
                                <div className="grid grid-cols-1 lg:grid-cols-2 gap-3 animate-fade-in">
                                    {visibleKeys.map(key => {
                                        const value = parsedData[section][key];
                                        const isBool = value.toLowerCase() === 'true' || value.toLowerCase() === 'false';

                                        // Robust key cleaning for translation: remove optional "scum." prefix (case-insensitive)
                                        const cleanKey = key.replace(/^scum\./i, '');
                                        // Try exact key first, then cleaned key
                                        const transKey = getSettingTranslation(key) || getSettingTranslation(cleanKey);
                                        // Use dynamic translation lookup for description
                                        const description = getSettingDescription(key) || getSettingDescription(cleanKey);

                                        return (
                                            <div 
                                                key={key} 
                                                className="bg-scum-800/30 rounded-lg border border-white/5 hover:bg-scum-800/50 transition-colors group px-4 py-3 flex flex-col gap-2 relative overflow-visible"
                                            >
                                                {/* Tooltip Popup */}
                                                {description && (
                                                    <div className="absolute left-0 bottom-full mb-2 w-full z-50 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-200 px-2 transform translate-y-1 group-hover:translate-y-0">
                                                        <div className="bg-black/90 text-gray-300 text-xs p-3 rounded-lg border border-scum-accent/30 shadow-[0_4px_20px_rgba(0,0,0,0.5)] backdrop-blur-md relative">
                                                            <div className="font-bold text-scum-accent mb-1 flex items-center gap-1">
                                                                <span className="w-1.5 h-1.5 rounded-full bg-scum-accent"></span> 
                                                                Info
                                                            </div>
                                                            <div className="whitespace-pre-wrap leading-relaxed">{description}</div>
                                                            {/* Arrow */}
                                                            <div className="absolute top-full left-6 -mt-[1px] border-4 border-transparent border-t-black/90"></div>
                                                        </div>
                                                    </div>
                                                )}

                                                <div className="flex flex-col mb-1 relative">
                                                    <label className="text-xs font-bold text-gray-200 group-hover:text-white transition-colors break-words flex items-center justify-between cursor-help">
                                                        <span>{transKey || cleanKey}</span>
                                                        {description && <div className="w-1.5 h-1.5 rounded-full bg-white/20 group-hover:bg-scum-accent/50 transition-colors"></div>}
                                                    </label>
                                                    {transKey && <span className="text-[9px] text-gray-500 font-mono truncate select-all">{key}</span>}
                                                </div>

                                                {isBool ? (
                                                    <div className="w-full">
                                                        <BooleanToggle 
                                                            label={""} 
                                                            value={value.toLowerCase() === 'true'}
                                                            onChange={(v) => handleUpdate(section, key, v)}
                                                            color={value.toLowerCase() === 'true' ? 'cyan' : 'fuchsia'}
                                                            size="sm"
                                                        />
                                                    </div>
                                                ) : (
                                                    <input 
                                                        type="text" 
                                                        className="w-full bg-black/30 border border-white/10 rounded px-2 py-1.5 text-sm text-white font-mono focus:outline-none focus:border-scum-accent transition-colors shadow-inner"
                                                        value={value}
                                                        onChange={(e) => handleUpdate(section, key, e.target.value)}
                                                    />
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    );
                })}

                {filteredSections.length === 0 && (
                    <div className="text-center py-12 text-gray-500 italic">No matching settings found.</div>
                )}
            </div>
        </div>
    );
};

import { fuzzyMatch } from './helpers';
import { fileTranslations } from './translations/fileTranslations';
import { nodeTranslations } from './translations/nodeTranslations';
import { itemTranslations } from './translations/itemTranslations';
import { serverSettingsTranslations } from './translations/serverSettingsTranslations';
import { serverSettingsDescriptions } from './translations/serverSettingsDescriptions';

// Types
export type TranslationCategory = 'item' | 'node' | 'file' | 'global' | 'setting' | 'setting_desc';

export interface TranslationEntry {
    text: string;
    categories: TranslationCategory[];
    masked?: boolean; // New flag: if true, this entry effectively "deletes" a default translation
}

export interface TranslationData {
    [key: string]: TranslationEntry;
}

const STORAGE_KEY_V1 = 'scum_translations';
const STORAGE_KEY_V2 = 'scum_translations_v2'; 
const STORAGE_KEY_V3 = 'scum_translations_v3'; 
const UPDATE_EVENT = 'scum_translations_updated';

// In-memory lookup maps
let itemMap: Record<string, string> = {};
let nodeMap: Record<string, string> = {};
let fileMap: Record<string, string> = {};
let settingsMap: Record<string, string> = {};
let settingDescMap: Record<string, string> = {};
let globalMap: Record<string, string> = {};

let customData: TranslationData = {};

const normalize = (key: string) => key.toLowerCase().trim();

const loadTranslations = () => {
    // 1. Load Defaults
    itemMap = { ...itemTranslations };
    nodeMap = { ...nodeTranslations };
    fileMap = { ...fileTranslations };
    settingsMap = { ...serverSettingsTranslations };
    settingDescMap = {};

    // Load descriptions with prefix
    Object.entries(serverSettingsDescriptions).forEach(([k, v]) => {
        settingDescMap[`DESC::${k}`] = v;
    });

    globalMap = {}; 

    // 2. Migration Logic (Simplified for V3 existing)
    try {
        const v3Stored = localStorage.getItem(STORAGE_KEY_V3);
        if (v3Stored) {
            customData = JSON.parse(v3Stored);
        } else {
            customData = {};
        }
    } catch (e) {
        console.warn("Translation load error", e);
        customData = {};
    }

    // 3. Populate Maps based on custom data overrides
    Object.entries(customData).forEach(([key, entry]) => {
        const { text, categories, masked } = entry;

        // If masked, we map it to the key itself (or empty string for descriptions) to simulate deletion
        const effectiveText = masked ? (categories.includes('setting_desc') ? "" : key) : text;

        if (categories.includes('global')) {
            globalMap[key] = effectiveText;
            itemMap[key] = effectiveText;
            nodeMap[key] = effectiveText;
            fileMap[key] = effectiveText;
            settingsMap[key] = effectiveText;
            settingDescMap[key] = effectiveText;
        } else {
            if (categories.includes('item')) itemMap[key] = effectiveText;
            if (categories.includes('node')) nodeMap[key] = effectiveText;
            if (categories.includes('file')) fileMap[key] = effectiveText;
            if (categories.includes('setting')) settingsMap[key] = effectiveText;
            if (categories.includes('setting_desc')) settingDescMap[key] = effectiveText;
        }
    });
};

loadTranslations();

if (typeof window !== 'undefined') {
    window.addEventListener('storage', (e) => {
        if (e.key === STORAGE_KEY_V3) {
            loadTranslations();
            window.dispatchEvent(new Event(UPDATE_EVENT));
        }
    });
}

export const subscribeToTranslationUpdates = (callback: () => void) => {
    const handler = () => callback();
    window.addEventListener(UPDATE_EVENT, handler);
    return () => window.removeEventListener(UPDATE_EVENT, handler);
};

// --- Lookup ---
const lookup = (key: string, primaryMap: Record<string, string>): string | null => {
    // 1. Exact Match in specific map (includes customs/masked)
    if (primaryMap[key]) return primaryMap[key];

    // 2. Check Custom Masking specifically if not found above but exists in customData as masked
    if (customData[key] && customData[key].masked) return key;

    // 3. Global Map
    if (globalMap[key]) return globalMap[key];

    // 4. Case-insensitive Search
    const lowerKey = normalize(key);
    const primaryMatch = Object.keys(primaryMap).find(k => normalize(k) === lowerKey);
    if (primaryMatch) return primaryMap[primaryMatch];

    const globalMatch = Object.keys(globalMap).find(k => normalize(k) === lowerKey);
    if (globalMatch) return globalMap[globalMatch];

    return null;
};

export const getItemTranslation = (id: string): string => lookup(id, itemMap) || id;
export const getNodeTranslation = (name: string): string => lookup(name, nodeMap) || name;
export const getFilePartTranslation = (part: string): string => lookup(part, fileMap) || part;
export const getSettingTranslation = (key: string): string => lookup(key, settingsMap) || "";
export const getSettingDescription = (key: string): string => lookup(`DESC::${key}`, settingDescMap) || "";

export const getFileNameTranslation = (filename: string): string => {
    const baseName = filename.replace(/\.json$/i, '');
    const parts = baseName.split(/([-_ ])/); 
    const translatedParts = parts.map(part => {
        if (part === '-' || part === '_' || part === ' ') return part;
        const translated = getFilePartTranslation(part);
        return translated !== part ? translated : part;
    });
    return translatedParts.join('');
};

export const hasTranslation = (id: string): boolean => {
    // Check custom masked first - if masked, we treat it as "no translation" for UI coloring purposes usually, 
    // BUT functionally it returns the ID. 
    // Here we return true if there is a translation entry (default or custom active).
    // If masked, we technically "have" a translation entry that says "don't translate".
    if (customData[id]?.masked) return false; 

    if (itemMap[id] || nodeMap[id] || fileMap[id] || globalMap[id] || settingsMap[id]) return true;
    const lower = normalize(id);
    const search = (map: Record<string, string>) => Object.keys(map).some(k => normalize(k) === lower);
    return search(itemMap) || search(nodeMap) || search(fileMap) || search(globalMap) || search(settingsMap);
};

// --- Management ---

export const saveTranslation = (key: string, value: string, category: TranslationCategory) => {
    const existing = customData[key];
    let newCategories: TranslationCategory[] = [];

    if (existing) {
        newCategories = [...existing.categories];
        if (category === 'global') {
            newCategories = ['global'];
        } else {
            if (!newCategories.includes(category)) {
                newCategories.push(category);
            }
        }
    } else {
        newCategories = [category];
    }

    customData[key] = { text: value, categories: newCategories, masked: false };
    localStorage.setItem(STORAGE_KEY_V3, JSON.stringify(customData));
    loadTranslations();
    window.dispatchEvent(new Event(UPDATE_EVENT));
};

export const toggleTranslationCategory = (key: string, category: TranslationCategory, value: string) => {
    const existing = customData[key];
    let newCategories: TranslationCategory[] = existing ? [...existing.categories] : [];

    if (category === 'global') {
        if (newCategories.includes('global')) return; 
        newCategories = ['global'];
    } else {
        if (newCategories.includes('global')) newCategories = []; 

        if (newCategories.includes(category)) {
            newCategories = newCategories.filter(c => c !== category);
        } else {
            newCategories.push(category);
        }
    }

    if (newCategories.length === 0) {
        deleteTranslation(key); // Use smart delete
    } else {
        customData[key] = { text: value, categories: newCategories, masked: false };
        localStorage.setItem(STORAGE_KEY_V3, JSON.stringify(customData));
        loadTranslations();
        window.dispatchEvent(new Event(UPDATE_EVENT));
    }
};

/**
 * Deletes a translation.
 * If the translation exists in the hardcoded defaults, it "masks" it (hides the default).
 * If it's pure custom, it removes it entirely.
 */
export const deleteTranslation = (key: string) => {
    // Check if it exists in defaults
    let isDefault = false;
    if (itemTranslations[key] || nodeTranslations[key] || fileTranslations[key] || serverSettingsTranslations[key] || serverSettingsDescriptions[key.replace('DESC::', '')]) {
        isDefault = true;
    }

    if (isDefault) {
        // Mask it instead of deleting
        const current = customData[key];
        customData[key] = { 
            text: key, 
            categories: current ? current.categories : ['global'], // Keep categories or default to global
            masked: true 
        };
    } else {
        // Truly delete
        delete customData[key];
    }

    localStorage.setItem(STORAGE_KEY_V3, JSON.stringify(customData));
    loadTranslations();
    window.dispatchEvent(new Event(UPDATE_EVENT));
};

export const bulkSaveTranslations = (updates: { key: string, value: string, category: TranslationCategory }[]) => {
    updates.forEach(item => {
        saveTranslation(item.key, item.value, item.category);
    });
};

export const bulkDeleteTranslations = (keys: string[]) => {
    keys.forEach(key => {
        deleteTranslation(key);
    });
};

export const importTranslations = (jsonContent: any) => {
    try {
        Object.entries(jsonContent).forEach(([k, v]: [string, any]) => {
            if (typeof v === 'string') {
                customData[k] = { text: v, categories: ['global'], masked: false };
            } else if (typeof v === 'object' && (v.text || v.masked)) {
                const cats = Array.isArray(v.categories) ? v.categories : (v.category ? [v.category] : ['global']);
                customData[k] = { text: v.text || k, categories: cats, masked: !!v.masked };
            }
        });
        localStorage.setItem(STORAGE_KEY_V3, JSON.stringify(customData));
        loadTranslations();
        window.dispatchEvent(new Event(UPDATE_EVENT));
        return true;
    } catch(e) {
        return false;
    }
};

export const exportTranslations = (): string => {
    return JSON.stringify(customData, null, 4);
};

export const resetTranslations = () => {
    localStorage.removeItem(STORAGE_KEY_V3);
    loadTranslations();
    window.dispatchEvent(new Event(UPDATE_EVENT));
};

// Returns merged list of defaults and customs. 
// If a default is masked, it is returned with isMasked=true and value=key
export const getAllTranslations = (modeFilter?: 'items' | 'server' | 'files'): { key: string, value: string, categories: TranslationCategory[], isCustom: boolean, isMasked: boolean }[] => {
    const list: { key: string, value: string, categories: TranslationCategory[], isCustom: boolean, isMasked: boolean }[] = [];
    const seen = new Set<string>();

    // Helper to check if category matches mode
    const matchesMode = (cats: TranslationCategory[]) => {
        if (!modeFilter) return true;
        if (cats.includes('global')) return true; // Global shows everywhere? Or maybe restrictive? Let's show everywhere.
        if (modeFilter === 'items') return cats.includes('item') || cats.includes('node');
        if (modeFilter === 'server') return cats.includes('setting') || cats.includes('setting_desc');
        if (modeFilter === 'files') return cats.includes('file');
        return false;
    };

    // 1. Add Custom Data (including masks)
    Object.entries(customData).forEach(([k, v]) => {
        if (!matchesMode(v.categories)) return;

        list.push({ 
            key: k, 
            value: v.masked ? (v.categories.includes('setting_desc') ? "" : k) : v.text, 
            categories: v.categories, 
            isCustom: true,
            isMasked: !!v.masked
        });
        seen.add(k);
    });

    // 2. Add Defaults (if not seen)
    const addDefaults = (map: Record<string, string>, cat: TranslationCategory, mapPrefix = "") => {
        // Optimization: Only scan maps relevant to mode
        if (modeFilter === 'items' && !['item', 'node'].includes(cat)) return;
        if (modeFilter === 'server' && !['setting', 'setting_desc'].includes(cat)) return;
        if (modeFilter === 'files' && cat !== 'file') return;

        Object.entries(map).forEach(([k, v]) => {
            const fullKey = mapPrefix ? `${mapPrefix}${k}` : k;
            if (!seen.has(fullKey)) {
                list.push({ key: fullKey, value: v, categories: [cat], isCustom: false, isMasked: false });
                seen.add(fullKey);
            }
        });
    };

    addDefaults(itemTranslations, 'item');
    addDefaults(nodeTranslations, 'node');
    addDefaults(fileTranslations, 'file');
    addDefaults(serverSettingsTranslations, 'setting');
    addDefaults(settingDescMap, 'setting_desc'); // Note: These keys already have DESC:: prefix in the map

    return list.sort((a, b) => a.key.localeCompare(b.key));
};

export const getIdsByTranslationMatch = (term: string): string[] => {
    if (!term) return [];
    const lower = normalize(term);
    const all = getAllTranslations(); // Search all, ignoring mode
    // Filter out masked items from search results usually? Or include them?
    // If masked, value == key, so it works naturally.
    return all.filter(t => !t.isMasked && t.value.toLowerCase().includes(lower)).map(t => t.key);
};

export const getIdsByFuzzyTranslationMatch = (term: string): string[] => {
    if (!term) return [];
    const all = getAllTranslations();
    return all.filter(t => !t.isMasked && fuzzyMatch(t.value, term)).map(t => t.key);
};

import React, { useState, useMemo, useEffect } from 'react';
import { useI18n } from '../i18n';
import { getAllTranslations, saveTranslation, deleteTranslation, importTranslations, exportTranslations, resetTranslations, subscribeToTranslationUpdates, TranslationCategory, bulkSaveTranslations, bulkDeleteTranslations, toggleTranslationCategory } from '../utils/itemTranslator';
import { SearchIcon, ArrowPathIcon, ArrowDownTrayIcon, ArrowUpTrayIcon, TrashIcon, PlusIcon, CheckCircleIcon, XMarkIcon } from './Icons';

interface TranslationManagerProps {
    onBack: () => void;
    mode?: 'items' | 'server' | 'files'; // New Prop
}

type FilterCategory = TranslationCategory | 'all' | 'custom';

export const TranslationManager: React.FC<TranslationManagerProps> = ({ onBack, mode = 'items' }) => {
    const { t } = useI18n();
    const [searchTerm, setSearchTerm] = useState("");
    const [filterCategory, setFilterCategory] = useState<FilterCategory>('all');
    const [translations, setTranslations] = useState<{ key: string, value: string, categories: TranslationCategory[], isCustom: boolean, isMasked: boolean }[]>([]);

    // Default category based on mode
    const defaultCategory = useMemo(() => {
        if (mode === 'server') return 'setting';
        if (mode === 'files') return 'file';
        return 'item';
    }, [mode]);

    // Add New State
    const [newKey, setNewKey] = useState("");
    const [newValue, setNewValue] = useState("");
    const [newCategory, setNewCategory] = useState<TranslationCategory>(defaultCategory);

    // Edit State
    const [editingKey, setEditingKey] = useState<string | null>(null);
    const [editingValue, setEditingValue] = useState("");

    // Bulk Edit State
    const [isBulkMode, setIsBulkMode] = useState(false);
    const [selectedKeys, setSelectedKeys] = useState<Set<string>>(new Set());

    const refreshData = () => {
        setTranslations(getAllTranslations(mode));
    };

    useEffect(() => {
        refreshData();
        const unsubscribe = subscribeToTranslationUpdates(() => {
            refreshData();
        });
        return () => unsubscribe();
    }, [mode]); // Refresh when mode changes

    useEffect(() => {
        setNewCategory(defaultCategory);
    }, [mode, defaultCategory]);

    const filteredList = useMemo(() => {
        let list = translations;

        if (filterCategory !== 'all') {
            if (filterCategory === 'custom') {
                list = list.filter((t) => t.isCustom);
            } else {
                // If filtering by specific category, show items that HAVE that category (or global)
                list = list.filter((t) => t.categories.includes(filterCategory as TranslationCategory) || t.categories.includes('global'));
            }
        }

        if (searchTerm) {
            const lower = searchTerm.toLowerCase();
            list = list.filter((t) => t.key.toLowerCase().includes(lower) || t.value.toLowerCase().includes(lower));
        }

        return list;
    }, [translations, filterCategory, searchTerm]);

    const handleSaveEdit = () => {
        if (editingKey) {
            const entry = translations.find(t => t.key === editingKey);
            if(entry) {
                const cat = entry.categories[0] || 'global';
                saveTranslation(editingKey, editingValue, cat);
            }
            setEditingKey(null);
        }
    };

    const handleDelete = (key: string) => {
        if (confirm(t('common.confirmDelete'))) {
            deleteTranslation(key);
        }
    };

    const handleAddNew = () => {
        if (!newKey || !newValue) return;

        let finalKey = newKey;
        // Auto-prefix for descriptions if user didn't type it
        if (newCategory === 'setting_desc' && !finalKey.startsWith('DESC::')) {
            finalKey = `DESC::${finalKey}`;
        }

        saveTranslation(finalKey, newValue, newCategory);
        setNewKey("");
        setNewValue("");
        setNewCategory(defaultCategory);
    };

    const handleExport = () => {
        const json = exportTranslations();
        const blob = new Blob([json], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `scum_translations_${mode}.json`;
        a.click();
    };

    const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (!e.target.files || e.target.files.length === 0) return;
        const file = e.target.files[0];
        const reader = new FileReader();
        reader.onload = (ev) => {
            try {
                const json = JSON.parse(ev.target?.result as string);
                if (importTranslations(json)) {
                    alert(t('settings.transImportSuccess'));
                } else {
                    alert(t('settings.transImportFail'));
                }
            } catch (err) {
                alert(t('settings.transImportFail'));
            }
        };
        reader.readAsText(file);
    };

    const handleReset = () => {
        if(confirm(t('trans.confirmReset'))) resetTranslations();
    };

    const toggleBulkMode = () => {
        setIsBulkMode(!isBulkMode);
        setSelectedKeys(new Set());
    };

    const handleSelect = (key: string) => {
        const newSet = new Set(selectedKeys);
        if (newSet.has(key)) newSet.delete(key);
        else newSet.add(key);
        setSelectedKeys(newSet);
    };

    const handleSelectAll = () => {
        if (selectedKeys.size === filteredList.length) {
            setSelectedKeys(new Set());
        } else {
            const newSet = new Set(selectedKeys);
            filteredList.forEach(t => newSet.add(t.key));
            setSelectedKeys(newSet);
        }
    };

    const handleBulkDelete = () => {
        if (selectedKeys.size === 0) return;
